<script setup>
import { nextTick, reactive, ref, watch } from 'vue'; import MButton from '../../../components/mds/MButton.vue'; import MInput from '../../../components/mds/MInput.vue'; import MSelect from '../../../components/mds/MSelect.vue'; import MTextarea from '../../../components/mds/MTextarea.vue'; import { PARTNER_TYPES, partnerCreateDraft, partnerTypeMeta, toPartnerCreatePayload, validatePartnerCreateDraft } from '../domain/partner-list.mjs';
const props=defineProps({type:String,saving:Boolean,serverError:String});const emit=defineEmits(['cancel','save']);const draft=reactive(partnerCreateDraft(props.type));const errors=reactive({});const nameInput=ref(null);watch(()=>props.type,(type)=>Object.assign(draft,partnerCreateDraft(type)));const tiers=['','Chiến lược','Quan trọng','Phát triển','Theo dõi'].map((value)=>({value,label:value||'Chưa xếp cấp độ'}));const adminLevels=['','Trung ương','Tỉnh/Thành phố','Quận/Huyện','Khác'].map((value)=>({value,label:value||'Chưa chọn'}));function validate(){const next=validatePartnerCreateDraft(draft);Object.keys(errors).forEach((key)=>delete errors[key]);Object.assign(errors,next);return next;}async function submit(){if(Object.keys(validate()).length){await nextTick();nameInput.value?.focus();return;}emit('save',toPartnerCreatePayload(draft));}
</script>
<template><section class="min-h-0 bg-[var(--mds-bg-page)] p-4"><form class="mx-auto max-w-[880px] rounded-lg bg-[var(--mds-bg)] shadow-[var(--mds-shadow-card)]" novalidate @submit.prevent="submit"><header class="flex items-start justify-between gap-4 border-b border-[var(--mds-border-light)] px-5 py-4"><div><h1 class="text-[20px] font-semibold">Thêm {{ partnerTypeMeta(draft.org_type).label.toLowerCase() }}</h1><p class="mt-1 text-[13px] text-[var(--mds-text-secondary)]">Nhập thông tin nhận diện ban đầu. Hội phí, tài trợ, MOU và tệp nằm ở luồng nghiệp vụ riêng có kiểm quyền.</p></div><MButton variant="neutral" :disabled="saving" @click="emit('cancel')">Hủy</MButton></header><div class="grid gap-4 p-5 sm:grid-cols-2"><label class="block sm:col-span-2"><span class="mb-1.5 block text-[13px] font-medium">Tên cơ quan <span class="text-[var(--mds-danger)]">*</span></span><MInput ref="nameInput" v-model="draft.name" :error="errors.name" :disabled="saving" placeholder="Nhập tên cơ quan"/></label><label class="block"><span class="mb-1.5 block text-[13px] font-medium">Nhóm cơ quan <span class="text-[var(--mds-danger)]">*</span></span><MSelect v-model="draft.org_type" :options="PARTNER_TYPES" :error="errors.org_type" :disabled="saving"/></label><label class="block"><span class="mb-1.5 block text-[13px] font-medium">Cấp độ quan hệ</span><MSelect v-model="draft.tier" :options="tiers" :disabled="saving"/></label><label class="block"><span class="mb-1.5 block text-[13px] font-medium">Ngày thành lập</span><MInput v-model="draft.founded_date" type="date" :disabled="saving"/></label><label class="block"><span class="mb-1.5 block text-[13px] font-medium">Đơn vị chủ quản</span><MInput v-model="draft.parent_org" :disabled="saving"/></label><label class="block"><span class="mb-1.5 block text-[13px] font-medium">Website</span><MInput v-model="draft.website" type="url" placeholder="https://…" :disabled="saving"/></label><label class="block"><span class="mb-1.5 block text-[13px] font-medium">Địa chỉ</span><MInput v-model="draft.address" :disabled="saving"/></label><template v-if="draft.org_type==='association'"><label class="block"><span class="mb-1.5 block text-[13px] font-medium">Tên viết tắt</span><MInput v-model="draft.abbreviation" :disabled="saving"/></label><label class="block"><span class="mb-1.5 block text-[13px] font-medium">Lĩnh vực hoạt động</span><MInput v-model="draft.field_area" :disabled="saving"/></label></template><template v-if="draft.org_type==='gov'"><label class="block"><span class="mb-1.5 block text-[13px] font-medium">Cấp quản lý</span><MSelect v-model="draft.admin_level" :options="adminLevels" :disabled="saving"/></label><label class="block"><span class="mb-1.5 block text-[13px] font-medium">Khối cơ quan</span><MInput v-model="draft.agency_block" :disabled="saving"/></label></template><label class="block sm:col-span-2"><span class="mb-1.5 block text-[13px] font-medium">Ghi chú</span><MTextarea v-model="draft.note" :rows="3" maxlength="2000" :disabled="saving"/></label></div><p v-if="serverError" role="alert" class="mx-5 mb-4 rounded-lg bg-[var(--mds-danger-bg)] px-3 py-2 text-[13px] text-[var(--mds-danger)]">{{ serverError }}</p><footer class="sticky bottom-0 flex justify-end gap-2 border-t border-[var(--mds-border-light)] bg-[var(--mds-bg)] px-5 py-3"><MButton variant="neutral" :disabled="saving" @click="emit('cancel')">Hủy</MButton><MButton variant="primary" :loading="saving" :disabled="saving" @click="submit">Tạo cơ quan</MButton></footer></form></section></template>
